async function checkAcces (_event) {
  function doCard (card) {
    external_commonjs_solid_ui_commonjs2_solid_ui_amd_solid_ui_root_UI_.acl.fixIndividualCardACL(card, (msg) => toolsPane_log(logSpace, msg), function (ok, message) {
      if (ok) {
        toolsPane_log(logSpace, 'Success for ' + external_commonjs_solid_ui_commonjs2_solid_ui_amd_solid_ui_root_UI_.utils.label(card))
      } else {
        error('Failure for ' + card + ': ' + message)
        toolsPane_log(logSpace, 'Failure for ' + card + ': ' + message)
      }
    })
  }
  const gg = []
  for (const g in toolsPane_selectedGroups) {
    gg.push(g)
  }

  for (let i = 0; i < gg.length; i++) {
    const g = toolsPane_kb.sym(gg[i])
    const a = groupMembers(toolsPane_kb, g)
    toolsPane_log(logSpace, external_commonjs_solid_ui_commonjs2_solid_ui_amd_solid_ui_root_UI_.utils.label(g) + ': ' + a.length + ' members')
    for (let j = 0; j < a.length; j++) {
      const card = a[j]
      toolsPane_log(logSpace, external_commonjs_solid_ui_commonjs2_solid_ui_amd_solid_ui_root_UI_.utils.label(card))
      doCard(card)
    }
  }
}

function toolsPane_log (logSpace, message) {
  logSpace.textContent += message + '\n'
}

function stats (logSpace) {
  const totalContacts = toolsPane_kb.each(undefined, VCARD('inAddressBook'), toolsPane_book).length
  toolsPane_log(logSpace, '' + totalContacts + ' contacts loaded. ')
  let groups = toolsPane_kb.each(toolsPane_book, VCARD('includesGroup'))
  const strings = new Set(groups.map(group => normalizeGroupUri(group.uri))) // remove dups with normalized URIs
  groups = [...strings].map(uri => toolsPane_kb.sym(uri))
  toolsPane_log(logSpace, '' + groups.length + ' total groups. ')
  const gg = []
  for (const g in toolsPane_selectedGroups) {
    gg.push(g)
  }
  toolsPane_log(logSpace, '' + gg.length + ' selected groups. ')
}

async function loadIndexHandler (loadIndexButton, logSpace) {
  loadIndexButton.classList.add('toolsButton--loading')
  loadIndexButton.classList.remove('toolsButton--error', 'toolsButton--success')
  const nameEmailIndex = toolsPane_kb.any(toolsPane_book, toolsPane_ns.vcard('nameEmailIndex'))
  try {
    await toolsPane_kb.fetcher.load(nameEmailIndex)
  } catch (e) {
    loadIndexButton.classList.remove('toolsButton--loading')
    loadIndexButton.classList.add('toolsButton--error')
    toolsPane_log(logSpace, 'Error: People index has NOT been loaded' + e + '\n')
  }
  loadIndexButton.classList.remove('toolsButton--loading')
  loadIndexButton.classList.add('toolsButton--success')
  toolsPane_log(logSpace, ' People index has been loaded\n')
} // loadIndexHandler

async function fixGroupless (book) {
  const groupless = await getGroupless(book)
  if (groupless.length === 0) {
    toolsPane_log(logSpace, 'No groupless contacts found.')
    return
  }
  let groupOfUngrouped = null
  try {
    groupOfUngrouped = await saveNewGroup(book, 'No group')
  } catch (_e) {
    // do nothing
  }

  const dom = logSpace.ownerDocument
  return new Promise(function (resolve) {
    const msg = dom.createElement('p')
    msg.textContent = `Add the ${groupless.length} contacts without groups to a 'No group' group?`
    logSpace.appendChild(msg)
    const confirmButton = external_commonjs_solid_ui_commonjs2_solid_ui_amd_solid_ui_root_UI_.widgets.continueButton(dom, async function () {
      msg.remove()
      confirmButton.remove()
      for (const person of groupless) {
        if (groupOfUngrouped) {
          toolsPane_log(logSpace, '   adding ' + external_commonjs_solid_ui_commonjs2_solid_ui_amd_solid_ui_root_UI_.utils.label(person))
          await addPersonToGroup(person, groupOfUngrouped)
        }
      }
      toolsPane_log(logSpace, 'People moved to group.')
      if (refreshGroupsFn) refreshGroupsFn()
      resolve()
    })
    logSpace.appendChild(confirmButton)
  })
}

async function getGroupless (book) {
  const groupIndex = toolsPane_kb.any(book, toolsPane_ns.vcard('groupIndex'))
  const nameEmailIndex = toolsPane_kb.any(book, toolsPane_ns.vcard('nameEmailIndex'))
  try {
    await toolsPane_kb.fetcher.load([nameEmailIndex, groupIndex])
    const groups = toolsPane_kb.each(book, toolsPane_ns.vcard('includesGroup'))
    await toolsPane_kb.fetcher.load(groups)
  } catch (e) {
    error('Error loading groups. Stack: ' + e)
    toolsPane_log(logSpace, 'Error loading groups or name index. If it persists, contact your admin.')
  }

  const reverseIndex = {}
  const groupless = []
  let groups = toolsPane_kb.each(book, VCARD('includesGroup'))
  const strings = new Set(groups.map(group => normalizeGroupUri(group.uri))) // remove dups with normalized URIs
  groups = [...strings].map(uri => toolsPane_kb.sym(uri))
  toolsPane_log(logSpace, '' + groups.length + ' total groups. ')

  for (let i = 0; i < groups.length; i++) {
    const g = groups[i]
    const a = groupMembers(toolsPane_kb, g)

    toolsPane_log(logSpace, external_commonjs_solid_ui_commonjs2_solid_ui_amd_solid_ui_root_UI_.utils.label(g) + ': ' + a.length + ' members')
    for (let j = 0; j < a.length; j++) {
      toolsPane_kb.allAliases(a[j]).forEach(function (y) {
        reverseIndex[y.uri] = g
      })
    }
  }

  const cards = toolsPane_kb.each(undefined, VCARD('inAddressBook'), book)
  toolsPane_log(logSpace, '' + cards.length + ' total contatcs')
  for (let c = 0; c < cards.length; c++) {
    if (!reverseIndex[cards[c].uri]) {
      groupless.push(cards[c])
      toolsPane_log(logSpace, '   groupless ' + external_commonjs_solid_ui_commonjs2_solid_ui_amd_solid_ui_root_UI_.utils.label(cards[c]))
    }
  }
  toolsPane_log(logSpace, '' + groupless.length + ' groupless contacts.')
  return groupless
}

