/* Query a database using SPARQL SELECT
*/
async function queryPublicDataSelect(sparql, queryTarget) {
  if (!queryTarget.endpoint) throw new Error('Missing queryTarget.endpoint required for queryPublicDataSelect');
  const myUrlWithParams = new URL(queryTarget.endpoint);
  myUrlWithParams.searchParams.append('query', sparql);
  const queryURI = myUrlWithParams.href;
  src_debug/* log */.Rm(' queryPublicDataSelect uri: ' + queryURI);
  const headers = new Headers();
  headers.append('Accept', 'application/json');
  const options = {
    credentials: 'omit',
    // CORS - as we know it is public
    headers
  };
  const response = await external_SolidLogic_.store.fetcher?.webOperation('GET', queryURI, options);
  const text = response?.responseText || '';
  if (text.length === 0) throw new Error('No text back from query ' + queryURI);
  const text2 = fixWikidataJSON(text);
  const json = JSON.parse(text2);
  src_debug/* log */.Rm('    Query result JSON' + JSON.stringify(json, null, 4).slice(0, 100) + '...');
  const bindings = json.results.bindings;
  return bindings;
}

