// Make SELECT element to select subclasses
//
// If there is any disjoint union it will so a mutually exclusive dropdown
// Failing that it will do a multiple selection of subclasses.
// Callback takes (boolean ok, string errorBody)

function makeSelectForCategory(dom, kb, subject, category, dataDoc, callbackFunction) {
  const du = kb.any(category, ns.owl('disjointUnionOf'));
  let subs;
  let multiple = false;
  if (!du) {
    subs = kb.each(undefined, ns.rdfs('subClassOf'), category);
    multiple = true;
  } else {
    subs = du.elements;
  }
  debug('Select list length ' + subs.length);
  if (subs.length === 0) {
    return errorMessageBlock(dom, 'Can\'t do ' + (multiple ? 'multiple ' : '') + 'selector with no subclasses of category: ' + category);
  }
  if (subs.length === 1) {
    return errorMessageBlock(dom, 'Can\'t do ' + (multiple ? 'multiple ' : '') + 'selector with only 1 subclass of category: ' + category + ':' + subs[1]);
  }
  return makeSelectForClassifierOptions(dom, kb, subject, ns.rdf('type'), subs, {
    multiple,
    nullLabel: '* Select type *'
  }, dataDoc, callbackFunction);
}

/** Make SELECT element to select subclasses recurively
//
// It will so a mutually exclusive dropdown, with another if there are nested
// disjoint unions.
//
// @param  callbackFunction takes (boolean ok, string errorBody)
*/
function makeSelectForNestedCategory(dom, kb, subject, category, dataDoc, callbackFunction) {
  function update() {
    if (child) {
      container.removeChild(child);
      child = null;
    }
    if (select.currentURI && kb.any(kb.sym(select.currentURI), ns.owl('disjointUnionOf'))) {
      child = makeSelectForNestedCategory(dom, kb, subject, kb.sym(select.currentURI), dataDoc, callbackFunction);
      select.subSelect = child.firstChild;
      select.subSelect.superSelect = select;
      container.appendChild(child);
    }
  }
  const container = dom.createElement('span'); // Container
  let child = null;
  function onChange(ok, body) {
    if (ok) update();
    callbackFunction(ok, body);
  }
  const select = makeSelectForCategory(dom, kb, subject, category, dataDoc, onChange);
  container.appendChild(select);
  update();
  return container;
}

/*  Build a checkbox from a given statement(s)
 **
 **  If the source document is editable, make the checkbox editable
 **
 **  ins and sel are either statements *or arrays of statements* which should be
 **  made if the checkbox is checed and unchecked respectively.
 **  tristate: Allow ins, or del, or neither
 */
function buildCheckboxForm(dom, kb, lab, del, ins, form, dataDoc, tristate) {
  const box = dom.createElement('div');
  const rhs = renderNameValuePair(dom, kb, box, form, lab);
  const editable = kb.updater.editable(dataDoc.uri);
  const input = dom.createElement('button');
  const colorCarrier = input;
  input.style = style.checkboxInputStyle;
  rhs.appendChild(input);
  function fix(x) {
    if (!x) return []; // no statements
    if (x.object) {
      if (!x.why) {
        x.why = dataDoc; // be back-compaitible  with old code
      }
      return [x]; // one statements
    }
    if (x instanceof Array) return x;
    throw new Error('buildCheckboxForm: bad param ' + x);
  }
  ins = fix(ins);
  del = fix(del);
  function holdsAll(a) {
    const missing = a.filter(st => !kb.holds(st.subject, st.predicate, st.object, st.why));
    return missing.length === 0;
  }
  function refresh() {
    let state = holdsAll(ins);
    let displayState = state;
    if (del.length) {
      const negation = holdsAll(del);
      if (state && negation) {
        box.appendChild(errorMessageBlock(dom, 'Inconsistent data in dataDoc!\n' + ins + ' and\n' + del));
        return box;
      }
      if (!state && !negation) {
        state = null;
        const defa = kb.any(form, ns.ui('default'));
        displayState = defa ? defa.value === '1' : tristate ? null : false;
      }
    }
    input.state = state;
    input.textContent = {
      true: checkMarkCharacter,
      false: tristate ? cancelCharacter : ' ',
      // Just use blank when not tristate
      null: dashCharacter
    }[displayState];
  }
  refresh();
  if (!editable) return box;
  let isUpdating = false; // Prevent concurrent updates on double-click

  const boxHandler = function (_e) {
    if (isUpdating) {
      return; // Ignore clicks while update is in progress
    }
    isUpdating = true;
    input.disabled = true; // Disable button to provide user feedback
    let didFinishUpdate = false;
    const finishUpdate = function () {
      if (didFinishUpdate) return false;
      didFinishUpdate = true;
      isUpdating = false;
      input.disabled = false;
      return true;
    };
    const showUpdateError = function (errorBody) {
      colorCarrier.style.color = '#000';
      colorCarrier.style.backgroundColor = '#fee';
      box.appendChild(errorMessageBlock(dom, `Checkbox: Error updating dataDoc from ${input.state} to ${input.newState}:\n\n${errorBody}`));
    };
    colorCarrier.style.color = '#bbb'; // grey -- not saved yet
    const toDelete = input.state === true ? ins : input.state === false ? del : [];
    input.newState = input.state === null ? true : input.state === true ? false : tristate ? null : true;
    const toInsert = input.newState === true ? ins : input.newState === false ? del : [];
    src_debug/* log */.Rm(`  Deleting  ${toDelete}`);
    src_debug/* log */.Rm(`  Inserting ${toInsert}`);
    try {
      const updateResult = kb.updater.update(toDelete, toInsert, function (uri, success, errorBody) {
        if (!finishUpdate()) return;
        if (!success) {
          if (toDelete.why) {
            const hmmm = kb.holds(toDelete.subject, toDelete.predicate, toDelete.object, toDelete.why);
            if (hmmm) {
              src_debug/* log */.Rm(' @@@@@ weird if 409 - does hold statement');
            }
          }
          showUpdateError(errorBody);
        } else {
          colorCarrier.style.color = '#000';
          input.state = input.newState;
          input.textContent = {
            true: checkMarkCharacter,
            false: cancelCharacter,
            null: dashCharacter
          }[input.state]; // @@
        }
      });
      if (updateResult && typeof updateResult.then === 'function') {
        updateResult.catch(function (error) {
          if (!finishUpdate()) return;
          showUpdateError(error instanceof Error ? error.message : error);
        }).finally(function () {
          finishUpdate();
        });
      }
    } catch (error) {
      finishUpdate();
      throw error;
    }
  };
  input.addEventListener('click', boxHandler, false);
  return box;
}
